use super::BatchWorkspace;
use super::batch::{copy_column, copy_value};

pub(super) fn evaluate_batch<T: NativeFloat>(input: &[C<T>], output: &mut [C<T>], rows: usize, ctx: &Context<T>, workspace: &mut BatchWorkspace<T>) -> Result<(), String> {
    let inputs = rows.checked_mul(33).ok_or("batch input size overflow")?;
    let outputs = rows.checked_mul(13).ok_or("batch output size overflow")?;
    if input.len() != inputs || output.len() != outputs { return Err("batch buffer shape mismatch".into()); }
    if rows == 0 { return Ok(()); }
    if rows == 1 {
        let values = evaluate(input, ctx);
        for (target, source) in output.iter_mut().zip(&values) { copy_value(target, source); }
        return Ok(());
    }
    let (v, stride) = workspace.prepare(rows, 128)?;
    for lane in 0..rows { copy_value(&mut v[0 * stride + lane], &input[lane * 33 + 0]); }
    for lane in 0..rows { copy_value(&mut v[1 * stride + lane], &input[lane * 33 + 1]); }
    for lane in 0..rows { copy_value(&mut v[2 * stride + lane], &input[lane * 33 + 2]); }
    for lane in 0..rows { copy_value(&mut v[3 * stride + lane], &input[lane * 33 + 3]); }
    for lane in 0..rows { copy_value(&mut v[4 * stride + lane], &input[lane * 33 + 4]); }
    for lane in 0..rows { copy_value(&mut v[5 * stride + lane], &input[lane * 33 + 5]); }
    for lane in 0..rows { copy_value(&mut v[6 * stride + lane], &input[lane * 33 + 6]); }
    for lane in 0..rows { copy_value(&mut v[7 * stride + lane], &input[lane * 33 + 7]); }
    for lane in 0..rows { copy_value(&mut v[8 * stride + lane], &input[lane * 33 + 8]); }
    for lane in 0..rows { copy_value(&mut v[9 * stride + lane], &input[lane * 33 + 9]); }
    for lane in 0..rows { copy_value(&mut v[10 * stride + lane], &input[lane * 33 + 10]); }
    for lane in 0..rows { copy_value(&mut v[11 * stride + lane], &input[lane * 33 + 11]); }
    for lane in 0..rows { copy_value(&mut v[12 * stride + lane], &input[lane * 33 + 12]); }
    for lane in 0..rows { copy_value(&mut v[13 * stride + lane], &input[lane * 33 + 13]); }
    for lane in 0..rows { copy_value(&mut v[14 * stride + lane], &input[lane * 33 + 14]); }
    for lane in 0..rows { copy_value(&mut v[15 * stride + lane], &input[lane * 33 + 15]); }
    for lane in 0..rows { copy_value(&mut v[16 * stride + lane], &input[lane * 33 + 16]); }
    for lane in 0..rows { copy_value(&mut v[17 * stride + lane], &input[lane * 33 + 17]); }
    for lane in 0..rows { copy_value(&mut v[18 * stride + lane], &input[lane * 33 + 18]); }
    for lane in 0..rows { copy_value(&mut v[19 * stride + lane], &input[lane * 33 + 19]); }
    for lane in 0..rows { copy_value(&mut v[20 * stride + lane], &input[lane * 33 + 20]); }
    for lane in 0..rows { copy_value(&mut v[21 * stride + lane], &input[lane * 33 + 21]); }
    for lane in 0..rows { copy_value(&mut v[22 * stride + lane], &input[lane * 33 + 22]); }
    for lane in 0..rows { copy_value(&mut v[23 * stride + lane], &input[lane * 33 + 23]); }
    for lane in 0..rows { copy_value(&mut v[24 * stride + lane], &input[lane * 33 + 24]); }
    for lane in 0..rows { copy_value(&mut v[25 * stride + lane], &input[lane * 33 + 25]); }
    for lane in 0..rows { copy_value(&mut v[26 * stride + lane], &input[lane * 33 + 26]); }
    for lane in 0..rows { copy_value(&mut v[27 * stride + lane], &input[lane * 33 + 27]); }
    for lane in 0..rows { copy_value(&mut v[28 * stride + lane], &input[lane * 33 + 28]); }
    for lane in 0..rows { copy_value(&mut v[29 * stride + lane], &input[lane * 33 + 29]); }
    for lane in 0..rows { copy_value(&mut v[30 * stride + lane], &input[lane * 33 + 30]); }
    for lane in 0..rows { copy_value(&mut v[31 * stride + lane], &input[lane * 33 + 31]); }
    for lane in 0..rows { copy_value(&mut v[32 * stride + lane], &input[lane * 33 + 32]); }
    batch_body_0(v, stride, rows, 0, ctx);
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 0], &v[115 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 1], &v[116 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 2], &v[117 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 3], &v[118 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 4], &v[119 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 5], &v[120 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 6], &v[121 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 7], &v[122 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 8], &v[123 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 9], &v[124 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 10], &v[125 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 11], &v[126 * stride + lane]); }
    for lane in 0..rows { copy_value(&mut output[lane * 13 + 12], &v[127 * stride + lane]); }
    Ok(())
}

fn batch_body_0<T: NativeFloat>(v: &mut [C<T>], stride: usize, rows: usize, base: usize, ctx: &Context<T>) {
    batch_block_0(v, stride, rows, base, ctx);
    batch_block_1(v, stride, rows, base, ctx);
    batch_block_2(v, stride, rows, base, ctx);
    batch_block_3(v, stride, rows, base, ctx);
    batch_block_4(v, stride, rows, base, ctx);
}

